#define MR1_PARITY_FORCE 0x08
#define MR1_PARITY_NONE 0x10
#define MR1_MULTIDROP   0x18
#define MR1_PARITY_ODD  0x04  /* with parity, odd; forced, high */
#define MR1_BITS_MASK   0x03  /* 5 to 8 bits, 0 to 3 */
